\label{1.1}
	Let $M$ be a finite $R$-module and suppose one of the following cases holds:
	\begin{itemize}
		\item[(a)] $\operatorname{cd}(\mathfrak{a},R)\leq 1$ or $\dim R\leq 2$. See \cite{Mel}.
		\item[(b)] $\dim R/{\mathfrak{a}}\leq 1$. See \cite{BN}.
	\end{itemize}
	Then $\operatorname{H}^{i}_{\mathfrak{a}}(M)$ is $\mathfrak{a}$--cofinite for
	all $i\geq 0$.

\label{1.2}
	Let $M, N$ be two finite $R$-modules and suppose one of the following cases holds:

	\begin{itemize}
		\item[(a)] $\operatorname{cd}(\mathfrak{a},R)\leq 1$ or $\dim R\leq 2$. See \cite{MS1}.
		\item[(b)] $\dim R/{\mathfrak{a}}\leq 1$. See \cite{DH}.
	\end{itemize}
	Then $\operatorname{H}^{i}_{\mathfrak{a}}(N,M)$ is $\mathfrak{a}$--cofinite for
	all $i\geq 0$.

Let $\mathfrak{a}$ be an ideals of a Noetherian ring $R$, with $\dim R/{\mathfrak{a}}=1$. For an $R$-module $M$   and  integer  an  $r$ the following conditions are equivalent; 

	\begin{itemize}
		\item[(i)]$\operatorname{Supp}_R(\operatorname{H}^{i}_\mathfrak{a}(M))\subseteq \operatorname{Max}(R)$ for each $i>r$.
		\item[(ii)] $\operatorname{H}^{i}_\mathfrak{a}(M)$ is an Artinian $R$-module for each $i>r$.
		\item[(iii)] $\operatorname{H}^{i}_\mathfrak{a}(M)$ is an Artinian $\mathfrak{a}$-cofinte $R$-module for each $i>r$.
	\end{itemize}

\label{T:ET}
	For each $R$-module $M$ 
	which satisfies the equivalent conditions of Theorem \ref{T:E}
	and each finite $R$-module $N$ with support 
	in $\operatorname{V}(\mathfrak{a})$, the modules 
	$\operatorname{Ext}_R^i(N, M)$ and $\operatorname{Tor}_i^R(N,M)$ belong to $\mathcal S$.

\label{cof3}
	Let $M$ be an $R$-module and suppose one of the following cases holds:
	\begin{itemize}
		\item[(a)] $\operatorname{ara} (\mathfrak{a})\leq 1$;
		\item[(b)]  $\dim R/\mathfrak{a} \leq 1$;
		\item[(c)]  $\dim R\leq 2$.
	\end{itemize}
	Then,  $\operatorname{H}^{i}_\mathfrak{a}(M)$ is $\mathfrak{a}$-cofinite for all $i$ if and only if $\operatorname{Ext}^i_R(R/\mathfrak{a} ,M)$ is a finite $R$-module for all $i$.

\label{1}
	Let $X$ be a finite $R$--module, $M$ be an arbitrary $R$--module. Then the following statements hold true.

	\begin{itemize}                           
		\item[(a)] $\Gamma_{\mathfrak{a}}(X, M)\cong \operatorname{Hom}_{R}(X, \Gamma_\mathfrak{a} (M)).$

		\item[(b)] If $\operatorname{Supp}_R(X)\cap \operatorname{Supp}_R(M)\subseteq \operatorname{V}(\mathfrak{a})$, then $\operatorname{H}^{i}_{\mathfrak{a}}(X, M)\cong\operatorname{Ext}^i_{R}(X, M)$ for all $i$.
	\end{itemize}

\label{cof4}
	Let $M$ be an $R$-module and suppose one of the following cases holds:
	\begin{itemize}
		\item[(a)] $\operatorname{ara} (\mathfrak{a})\leq 1$;
		\item[(b)]  $\dim R/\mathfrak{a} \leq 1$;
		\item[(c)]  $\dim R\leq 2$.
	\end{itemize}
	Then, for any finite $R$-module $N$, $\operatorname{H}^{i}_\mathfrak{a}(N,M)$ is $\mathfrak{a}$-cofinite for all $i\geq 0$ if and only if $\operatorname{Ext}^i_R(R/\mathfrak{a} ,M)$ is finite $R$-module  for all $i\geq 0$.

First suppose for any finite $R$-module $N$, $\operatorname{H}^{i}_\mathfrak{a}(N,M)$ is $\mathfrak{a}$-cofinite for all $i\geq 0$. Let $N=R$, then it follows by Theorem \ref{cof3}, that $\operatorname{Ext}^i_R(R/\mathfrak{a} ,M)$ is finite $R$-module  for all $i\geq 0$.

	To prove the converse we use induction on $i$. Let $i=0$, then it follows by Lemma \ref{1} (a) that
	\begin{center}
		$\operatorname{H}^{0}_\mathfrak{a}(N,M)=\Gamma_{\mathfrak{a}}(N, M)\cong \operatorname{Hom}_{R}(N, \Gamma_\mathfrak{a} (M)).$
	\end{center}	

	Since $\Gamma_{\mathfrak{a}}(M)$ is $\mathfrak{a}$-cofinite by Theorem \ref{cof3},
	so the assertion follows by \cite[Theorem 4.1]{BA}, \cite[Corollary 2.7]{Mel1} and \cite[Theorem 7.4]{Mel}, respectively in the cases (a), (b) and (c). Now assume that $i> 0$ and that the claim holds for $i-1$. Since $\operatorname{\Gamma}_{\mathfrak{a}}(M)$ is $\mathfrak{a}$-cofinite and $\operatorname{Ext}^i_R(R/\mathfrak{a} ,M)$ is finite $R$-module for all $i\ge 0$. Using the short exact sequence

	\begin{center}
		$0\longrightarrow \operatorname{\Gamma}_{\mathfrak{a}}(M)\longrightarrow M \longrightarrow M/\operatorname{\Gamma}_{\mathfrak{a}}(M)
		\longrightarrow 0,$
	\end{center}

	it is easy to see that  the $R$-modules ${\operatorname{Ext}}^{i}_R(R/{\mathfrak{a}},M/\operatorname{\Gamma}_{\mathfrak{a}}(M))$ are finite for all $i\ge 0$. Now, by applying the derived functor $\Gamma_{\mathfrak{a}}(N,-)$ to the same short exact sequence and using Lemma \ref{1} (b), we obtain the long exact sequence 

	\begin{center}
		$\dots \longrightarrow \operatorname{Ext}_R^i(N,\operatorname{\Gamma}_{\mathfrak{a}}(M))\overset{f_i} 
		\longrightarrow \operatorname{H}^{i}_\mathfrak{a}(N,M)\overset{g_i}\longrightarrow \operatorname{H}^{i}_\mathfrak{a}(N,M/\operatorname{\Gamma}_{\mathfrak{a}}(M))\overset{h_i}\longrightarrow \operatorname{Ext}_R^i(N,\operatorname{\Gamma}_{\mathfrak{a}}(M))\overset{f_{i+1}}\longrightarrow\operatorname{H}^{i+1}_\mathfrak{a}(N,M)\longrightarrow\dots$
	\end{center}

	which yields short exact sequences 

	\begin{center}
		$0\longrightarrow \operatorname{Ker}{f_i}\longrightarrow \operatorname{Ext}_R^i(N,\operatorname{\Gamma}_{\mathfrak{a}}(M)) \longrightarrow \operatorname{Im}{f_i}
		\longrightarrow 0,$
	\end{center}

	\begin{center}
		$0\longrightarrow \operatorname{Im}{f_i}\longrightarrow \operatorname{H}^{i}_\mathfrak{a}(N,M) \longrightarrow \operatorname{Im}{g_i}
		\longrightarrow 0$
	\end{center}

	\begin{center}
		$\text{and}$
	\end{center}

	\begin{center}
		$0\longrightarrow \operatorname{Im}{g_i}\longrightarrow \operatorname{H}^{i}_\mathfrak{a}(N,M/\operatorname{\Gamma}_{\mathfrak{a}}(M)) \longrightarrow \operatorname{Ker}{f_{i+1}}
		\longrightarrow 0.$
	\end{center}

	Since $\operatorname{Ext}_R^i(N,\operatorname{\Gamma}_{\mathfrak{a}}(M))$	is  $\mathfrak{a}$-cofinite $R$-module for all $i\ge 0$ by \cite[Theorem 4.1]{BA}, \cite[Corollary 2.7]{Mel1} and \cite[Theorem 7.4]{Mel}, respectively in the cases (a), (b) and (c), it follows by definition that, $\operatorname{H}^{i}_\mathfrak{a}(N,M)$ is $\mathfrak{a}$-cofinite $R$-module if and only if $\operatorname{H}^{i}_\mathfrak{a}(N,M/\operatorname{\Gamma}_{\mathfrak{a}}(M))$ is  $\mathfrak{a}$-cofinite $R$-module for all $i\ge 0$. Therefore it suffices to show that $\operatorname{H}^{i}_\mathfrak{a}(N,M/\operatorname{\Gamma}_{\mathfrak{a}}(M))$ is  $\mathfrak{a}$-cofinite $R$-module for all $i\ge 0$. To this end consider the exact sequence 

	\begin{center}
		$0\longrightarrow M/\operatorname{\Gamma}_{\mathfrak{a}}(M)\longrightarrow E \longrightarrow L
		\longrightarrow 0,\,\,\,\,\,\,\,\,(\dagger)$
	\end{center}

	in which $E$ is an injective $\mathfrak{a}$-torsion free module. Since 
	$\operatorname{\Gamma}_{\mathfrak{a}}(M/\operatorname{\Gamma}_{\mathfrak{a}}(M))= 0= \operatorname{\Gamma}_{\mathfrak{a}}(E)$, thus $\operatorname{Hom}_R(R/\mathfrak{a},E)=0$ and $\operatorname{\Gamma}_{\mathfrak{a}}(N, M/\operatorname{\Gamma}_{\mathfrak{a}}(M))= 0= \operatorname{\Gamma}_{\mathfrak{a}}(N, E)$ by Lemma \ref{1} (a). Applying the derived functors of $\operatorname{Hom}_R(R/\mathfrak{a},-)$ and $\Gamma_{\frak{a}}(N,-)$ to the short exact sequence $(\dagger)$
	we obtain, for all $i> 0$, the isomorphisms

	\begin{center}
		$\operatorname{H}^{i-1}_\mathfrak{a}(N, L)\cong \operatorname{H}^i_\mathfrak{a}(N,M/\operatorname{\Gamma}_{\mathfrak{a}}(M))$.

	\end{center}

	\begin{center}
		\text{and} 	
	\end{center}	 

	\begin{center}
		${\operatorname{Ext}}^{i-1}_R(R/{\mathfrak{a}},L)\cong {\operatorname{Ext}}^{i}_R(R/{\mathfrak{a}},M/\operatorname{\Gamma}_{\mathfrak{a}}(M))$.
	\end{center}

	From what has already been proved, we conclude that  ${\operatorname{Ext}}^{i-1}_R(R/{\mathfrak{a}},L)$ is finite for all $i>0$. Hence $\operatorname{H}^{i-1}_\mathfrak{a}(N, L)$ is $\mathfrak{a}$-cofinite by induction hypothesis for all $i>0$, which yields that $\operatorname{H}^i_\mathfrak{a}(N,M/\operatorname{\Gamma}_{\mathfrak{a}}(M))$ is $\mathfrak{a}$-cofinite for all $i\ge 0$, this completes the inductive step.

\label{min}
	Let $M$ be an $R$-module and suppose one of the following cases holds:
	\begin{itemize}
		\item[(a)] $\operatorname{ara} (\mathfrak{a})\leq 1$;
		\item[(b)]  $\dim R/\mathfrak{a} \leq 1$;
		\item[(c)]  $\dim R\leq 2$.
	\end{itemize}
	Then the following conditions
	are equivalent: 
	\begin{itemize}
		\item[(i)] $\operatorname{Ext}^i_R(R/\mathfrak{a} ,M)$ is finite for all $i$.
		\item[(ii)] $\operatorname{Ext}^i_R(R/\mathfrak{a} ,M)$ is finite for $i=0,1$ in the cases {\rm(}a{\rm)} and {\rm(}b{\rm)} {\rm(}resp. for $i=0,1,2$  in the case {\rm(}c{\rm)}{\rm)};
		\item[(iii)] $\operatorname{H}^{i}_\mathfrak{a}(M)$ is  $\mathfrak{a}$-cofinite  for all $i$;
		\item[(iv)]  $\operatorname{H}^{i}_\mathfrak{a}(N,M)$ is  $\mathfrak{a}$-cofinite
		for all $i$ and for any finite $R$-module $N$;
		\item[(v)] $\operatorname{Ext}^{i}_R(N,M)$ is  finite  for all $i$ and for any finite $R$-module $N$ with $\operatorname{Supp}_R(N)\subseteq \operatorname{V}(\mathfrak{a})$;
		\item[(vi)] $\operatorname{Ext}^{i}_R(N,M)$ is  finite  for all $i$ and for some finite $R$-module $N$ with $\operatorname{Supp}_R(N)=\operatorname{V}(\mathfrak{a})$;
		\item[(vii)] $\operatorname{Ext}^{i}_R(N,M)$ is  finite  for $i=0,1$ in the cases {\rm(}a{\rm)} and {\rm(}b{\rm)} {\rm(}resp. for $i=0,1,2$  in the case {\rm(}c{\rm)}{\rm)} and for any finite $R$-module $N$ with $\operatorname{Supp}_R(N)\subseteq \operatorname{V}(\mathfrak{a})$;
		\item[(viii)] $\operatorname{Ext}^{i}_R(N,M)$ is  finite  for $i=0,1$ in the cases {\rm(}a{\rm)} and {\rm(}b{\rm)} {\rm(}resp. for $i=0,1,2$  in the case {\rm(}c{\rm)}{\rm)} and for some finite $R$-module $N$ with $\operatorname{Supp}_R(N)=\operatorname{V}(\mathfrak{a})$.
	\end{itemize}

